function courseWord(level, code, index, item) {
  var values = Array.isArray(item) ? item : [item, '', 'Use the word in a sentence.', '📘'];
  return {
    id: 'course-' + level + '-' + code + '-' + index,
    word: values[0],
    malagasy: values[1] || '',
    example: values[2] || ('I can use ' + values[0] + '.'),
    emoji: values[3] || '📘',
  };
}

function courseLesson(level, code, label, mg, goal, grammar, outcomes, words, reading, writing, speaking, listening, spelling, review, sourceFocus) {
  return {
    id: 'course-' + level + '-' + code,
    level: level,
    label: label,
    mg: mg || '',
    goal: goal,
    grammar: grammar,
    outcomes: outcomes,
    words: words.map(function (item, index) { return courseWord(level, code, index + 1, item); }),
    reading: reading,
    writing: writing,
    speaking: speaking,
    listening: listening,
    spelling: spelling,
    review: review,
    sourceFocus: sourceFocus || '',
    lessonFlow: [
      'Preview the goal and say the key words aloud.',
      'Study the language pattern in the examples.',
      'Read, listen, speak, and write using the new language.',
      'Complete the review and explain one thing you can now do.',
    ],
  };
}

